import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"元宝教程","description":"打开元宝网页或客户端，发出第一句。只复述能在官方页核对的入口。","frontmatter":{"title":"元宝教程","description":"打开元宝网页或客户端，发出第一句。只复述能在官方页核对的入口。","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/yuanbao/yuanbao.md","filePath":"zh/products/yuanbao/yuanbao.md","lastUpdated":1787107158000}'),n={name:"zh/products/yuanbao/yuanbao.md"};function l(d,t,h,s,i,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="元宝教程" tabindex="-1">元宝教程 <a class="header-anchor" href="#元宝教程" aria-label="Permalink to &quot;元宝教程&quot;">​</a></h1><blockquote><p>先打开 <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a> 或 <a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">下载中心</a>。本页只复述能在官方页核对的入口和能力。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 第一次用元宝的前端工程师。首页按钮文案是 <strong>Log In</strong>；具体登录方式以页面为准。</p><p><strong>你会完成：</strong> 在网页或客户端里发出第一句；知道电脑版快捷键和官方能力边界。</p><p><strong>不会做：</strong> 注册微信/QQ 教程、CodeBuddy 安装、编造模型切换步骤、列出未公布的 36 种后缀。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>能打开 <code>yuanbao.tencent.com</code>（部分网络会把该域名解析到 <code>198.18.0.0/15</code>，先换 DNS / 关 Fake-IP 再判断「打不开」）。</li><li>客户端系统要求以官方页为准，两处不要混成一个数： <ul><li>下载中心：macOS <strong>11.3</strong> 及以上，Windows <strong>10</strong> 及以上。</li><li>App Store：iOS / iPadOS <strong>15.0</strong> 或更高版本。</li></ul></li></ul><h2 id="_15-分钟内打开" tabindex="-1">15 分钟内打开 <a class="header-anchor" href="#_15-分钟内打开" aria-label="Permalink to &quot;15 分钟内打开&quot;">​</a></h2><h3 id="_1-选一个官方入口" tabindex="-1">1. 选一个官方入口 <a class="header-anchor" href="#_1-选一个官方入口" aria-label="Permalink to &quot;1. 选一个官方入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>端</th><th>怎么走</th><th>来源</th></tr></thead><tbody><tr><td>网页</td><td>打开 <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>，点 <strong>Log In</strong></td><td>首页</td></tr><tr><td>网页（电脑版落地页）</td><td><a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a> 点 <strong>使用网页版</strong></td><td>电脑版页</td></tr><tr><td>iOS</td><td>下载中心扫码，或 App Store「元宝-腾讯全能AI助手」（id <code>6480446430</code>）</td><td><a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download</a>、<a href="https://apps.apple.com/cn/app/%E5%85%83%E5%AE%9D-%E8%85%BE%E8%AE%AF%E5%85%A8%E8%83%BDai%E5%8A%A9%E6%89%8B/id6480446430" target="_blank" rel="noreferrer">App Store</a></td></tr><tr><td>Android</td><td>下载中心扫码，或 Play 包名 <code>com.tencent.hunyuan.app.chat</code></td><td><a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download</a>、<a href="https://play.google.com/store/apps/details?id=com.tencent.hunyuan.app.chat" target="_blank" rel="noreferrer">Play</a></td></tr><tr><td>Windows / macOS</td><td>下载中心，或电脑版页 <strong>下载电脑版</strong>；Windows 也可走 <a href="https://pc.qq.com/detail/1/detail_36661.html" target="_blank" rel="noreferrer">腾讯软件中心</a></td><td><a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download</a>、<a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a></td></tr></tbody></table><p>协议还写了<strong>小程序</strong>和<strong>浏览器插件</strong>（<a href="https://rule.tencent.com/rule/202403110001" target="_blank" rel="noreferrer">用户服务协议</a>）。2026-08-19 没有找到这两个形态的官方独立安装页，本教程不写步骤。</p><p>旧地址 <code>https://hunyuan.tencent.com/bot/chat</code> 的 canonical 已是元宝站，不要收藏成「混元聊天」。</p><h3 id="_2-发出第一句" tabindex="-1">2. 发出第一句 <a class="header-anchor" href="#_2-发出第一句" aria-label="Permalink to &quot;2. 发出第一句&quot;">​</a></h3><p>首页未登录可见：「Hi, 我是元宝」「聊天、写作、搜索都在行，助你灵感无限」。登录后在输入框提问，或把文件拖进去（首页写了 <strong>Drag the file here to upload</strong>）。</p><p>页面底部有「内容由AI生成，仅供参考」。把它当产品声明，不当免责套话忽略。</p><h3 id="_3-电脑版-划词和迷你窗" tabindex="-1">3. 电脑版：划词和迷你窗 <a class="header-anchor" href="#_3-电脑版-划词和迷你窗" aria-label="Permalink to &quot;3. 电脑版：划词和迷你窗&quot;">​</a></h3><p>只在需要桌面唤起时装客户端。官方电脑版页（<a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a>）写明：</p><table tabindex="0"><thead><tr><th>动作</th><th>官方原文</th></tr></thead><tbody><tr><td>迷你对话窗</td><td>「按下快捷键Option+空格（mac）或Alt+空格（window），快速调用迷你对话窗」</td></tr><tr><td>划词</td><td>「支持 AI 划词搜索、翻译，什么都能问元宝」</td></tr><tr><td>识图</td><td>「截图上传即可搜索，即问即答效率倍增」</td></tr><tr><td>临时对话</td><td>「临时对话不会显示在历史对话记录中」</td></tr><tr><td>收藏</td><td>「精彩回答一键收藏」</td></tr></tbody></table><p>软件中心电脑版还写了：全局划词（一键翻译、搜索、朗读，对话窗直显）；分组定制指令；直连腾讯文档导入与导出。</p><h2 id="官方能力-按出处分组" tabindex="-1">官方能力（按出处分组） <a class="header-anchor" href="#官方能力-按出处分组" aria-label="Permalink to &quot;官方能力（按出处分组）&quot;">​</a></h2><h3 id="首页在说什么" tabindex="-1">首页在说什么 <a class="header-anchor" href="#首页在说什么" aria-label="Permalink to &quot;首页在说什么&quot;">​</a></h3><p><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a> description：</p><blockquote><p>元宝是腾讯推出的全能 AI 助手，已接入最新的混元 Hy3 模型，拥有更强的文件处理交付能力，多种风格写作轻松驾驭、聊天陪伴更有人情味、AI 搜索更实用精准；智能识图、生图P图、拍题答疑等丰富能力，让您的工作学习生活更轻松高效。</p></blockquote><p>可见导航还有 <strong>Search</strong>、<strong>All Collections</strong>、<strong>Download Center</strong>。Collections / Group 的规则官方没有单独文档，本页不编。</p><h3 id="电脑版页在说什么" tabindex="-1">电脑版页在说什么 <a class="header-anchor" href="#电脑版页在说什么" aria-label="Permalink to &quot;电脑版页在说什么&quot;">​</a></h3><p><a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a> 五个栏目：<strong>混元 Hy3</strong>、<strong>AI 写作</strong>、<strong>AI 编程</strong>、<strong>AI 识图</strong>、<strong>AI 划词</strong>。</p><p>和编程相关的原文只有两句：</p><ul><li>「AI 编程无需部署，即时验证」</li><li>「支持Python、C++等多语言运行，无需部署即时验证」</li></ul><p>这是<strong>对话里跑代码</strong>，不是克隆仓库、开 PR、接 MCP。仓库级编码去 <a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">CodeBuddy</a>（本站 #78，这里不写教程）。</p><p>文件：「支持36种各式文件，代码、日志、技术文档都能读」。<strong>没有</strong>官方后缀表，不要补 PDF/DOCX 清单。</p><h3 id="商店长描述还列了什么" tabindex="-1">商店长描述还列了什么 <a class="header-anchor" href="#商店长描述还列了什么" aria-label="Permalink to &quot;商店长描述还列了什么&quot;">​</a></h3><p>App Store 与 Play「特色功能」在 2026-08-19 一致，包括：AI 图片编辑、拍题答疑、<strong>元宝派（开启公测，支持在元宝派养龙虾）</strong>、AI 录音笔（转写翻译不限时）、秒写报告 / 文案 / 代码、AI 讲解、AI 生成视频、语音通话、识图、拍照翻译、QQ 音乐、AI 绘图、生态联动微信 / 腾讯文档 / 腾讯新闻 / 微信读书、公众号与视频号信源、文档精读 36 种文件类型、秒搜热搜。</p><p>「生态联动微信」是商店里的一句能力，<strong>不是</strong>微信接入教程。</p><p>元宝派只当元宝内的公测玩法，不单独开页。</p><h2 id="模型文案不要选边" tabindex="-1">模型文案不要选边 <a class="header-anchor" href="#模型文案不要选边" aria-label="Permalink to &quot;模型文案不要选边&quot;">​</a></h2><p>三处官方说法同时存在（2026-08-19）：</p><table tabindex="0"><thead><tr><th>出处</th><th>原文</th></tr></thead><tbody><tr><td>首页 / 电脑版页</td><td>已接入 / 展示 <strong>混元 Hy3</strong></td></tr><tr><td>App Store 版本说明</td><td>2.66–2.67「接入Hy3 preview」；2.76–2.78「Hy3模型正式上线」</td></tr><tr><td>Play「关于此应用」</td><td>「腾讯混元自研T1与DeepSeek R1双推理模型……」</td></tr></tbody></table><p>以你客户端里实际可选的名称为准。不要写「现在默认 DeepSeek」或「已经彻底下线 T1」。模型原理见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>。</p><h2 id="协议与数据" tabindex="-1">协议与数据 <a class="header-anchor" href="#协议与数据" aria-label="Permalink to &quot;协议与数据&quot;">​</a></h2><p>使用前打开：</p><ul><li><a href="https://rule.tencent.com/rule/202403110001" target="_blank" rel="noreferrer">元宝用户服务协议</a></li><li><a href="https://privacy.qq.com/document/preview/eb9be56572ab4886b6ca124e72abf413" target="_blank" rel="noreferrer">元宝隐私政策</a></li></ul><p>协议服务范围原文包括网页、PC 客户端、小程序、浏览器插件。条款正文在规则中心，需浏览器打开（无 JS 会空白）。本页不转述授权范围——以协议当前文本为准。</p><p>Play 支持邮箱：<code>yuanbao@tencent.com</code>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>把元宝当成 Claude Code / Cursor。</strong> 官方没有元宝 CLI，也没有官方 IDE 插件页。</li><li><strong>按博客里的「双模四模型」写进笔记。</strong> 那是旧文；当前首页写 Hy3，Play 简介仍提 T1 + R1。</li><li><strong>补全 36 种格式。</strong> 官方只给了数字和「代码、日志、技术文档」。</li><li><strong>为小程序 / 插件写安装步骤。</strong> 协议有名字，没有找到独立官方安装页。</li><li><strong>把 <code>hunyuan.tencent.com/bot/chat</code> 当成混元聊天产品。</strong> canonical 已指向元宝。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>回查入口和链接：<a href="./yuanbao-cheatsheet.html">速查表</a></li><li>分清名字：<a href="./yuanbao-glossary.html">术语表</a></li><li>回家族图：<a href="./">学习地图</a></li></ul>',48)])])}const m=a(n,[["render",l]]);export{f as __pageData,m as default};
